"""Complete 24 original respiratory-examination questions."""
from create_exam_respiratory_signs import rows,q,CH,OV,GI,ref
from qbank_authoring import finalize

q('A patient with severe hyperinflation has inward movement of the lower lateral ribs during inspiration. Which sign is described?', 'Hoover sign from altered diaphragmatic mechanics',[
 ('Flail-chest motion from multiple adjacent rib fractures','That is a localized unstable segment rather than the typical bilateral lower-rib pattern.'),('Normal outward lower-rib expansion','The observed motion is paradoxical.'),('A pleural friction phenomenon','This is a mechanical inspection sign rather than a rub.')],
 'A flattened diaphragm changes the direction of lower-rib force','**Hyperinflation can create inward lower-costal motion during inspiration.**',['The sign supports abnormal mechanics but does not measure obstruction severity exactly.','Do not confuse this with the neurological Hoover maneuver.'],'**Assess the broader obstructive pattern and objective physiology.**',['Review work of breathing and gas exchange.','Consider mixed disease if other signs are discordant.'],[['Respiratory Hoover','Lower ribs move inward'],['Mechanism','Flattened diaphragm geometry'],['Neurological Hoover','Different examination test']],[CH,OV],style='clinical_scenario')

q('During quiet inspiration, the abdomen moves inward rather than outward in a supine patient with orthopnea and limb weakness. Which possibility is important?', 'Diaphragmatic weakness or paralysis',[
 ('Normal diaphragmatic descent as the only explanation','Normal descent generally displaces the abdominal contents outward.'),('Isolated upper-airway stridor','This does not explain the typical abdominal paradox.'),('A diagnosis of pleural effusion from abdominal motion alone','The sign points to mechanics rather than confirming pleural fluid.')],
 'Inspect thorax and abdomen together','**A weak diaphragm can be drawn cranially by inspiratory pressure generated by other muscles.**',['The sign is often more evident supine.','Other causes of thoracoabdominal asynchrony exist.'],'**Assess neuromuscular and phrenic causes and ventilatory function.**',['Use appropriate spirometric, ultrasound or other testing.','Do not assume normal oxygen saturation excludes nocturnal hypoventilation.'],[['Normal','Abdomen usually outward on inspiration'],['Weak diaphragm','Possible inward paradox'],['Context','Supine symptoms/neuromuscular signs']],[CH,OV],style='clinical_scenario')

q('Marked sternocleidomastoid use and intercostal retraction are seen during quiet breathing. Which inference is appropriate?', 'The patient has increased respiratory effort requiring assessment of severity and cause',[
 ('These signs provide the exact arterial oxygen tension','They show effort rather than a blood-gas value.'),('They occur only in asthma','Several obstructive, restrictive and upper-airway problems can cause increased work.'),('They exclude impending fatigue if the respiratory rate falls','A falling rate can reflect exhaustion in a deteriorating patient.')],
 'Effort is a separate dimension from rate and oxygenation','**Accessory recruitment signals increased load or reduced capacity.**',['Look for speech limitation, posture, consciousness and chest-abdominal coordination.','Trend findings rather than judging one moment.'],'**Escalate evaluation and support when the patient is tiring.**',['Assess airway, lung, cardiac and neuromuscular causes.','Do not let an acceptable SpO2 obscure severe work of breathing.'],[['Rate','Frequency'],['Effort','Load/capacity balance'],['Fatigue','Can reduce apparent activity dangerously']],[CH])

q('A patient has cycles of gradually increasing and decreasing tidal volume followed by central apnea. Which pattern is described?', 'Cheyne–Stokes respiration',[
 ('Kussmaul breathing','This is sustained deep breathing in a metabolic-acidosis context.'),('Apneustic breathing','This involves abnormal prolonged inspiratory pauses rather than the crescendo–decrescendo cycle.'),('An isolated sigh','A sigh does not constitute repetitive periodic breathing with apnea.')],
 'Describe the temporal pattern before naming a cause','**Periodic waxing and waning ventilation reflects instability in respiratory control.**',['Heart failure, CNS disease, altitude and other contexts can produce it.','The sign is not specific for one lesion.'],'**Evaluate the underlying setting and clinical consequences.**',['Distinguish central apnea from obstructed efforts.','Assess sleep and cardiac/neurological disease as indicated.'],[['Pattern','Crescendo–decrescendo'],['Interval','Central apnea'],['Causes','Several control-loop contexts']],[OV],style='clinical_scenario')

q('A patient with severe metabolic acidosis has sustained deep, labored breathing. Which physiological interpretation is most appropriate?', 'Compensatory hyperventilation, classically termed Kussmaul breathing in the appropriate pattern',[
 ('Primary hypoventilation as the cause of a low PaCO2','The response increases ventilation and lowers CO2.'),('A pattern uniquely specific to DKA','Other severe metabolic acidemias can produce it.'),('Proof that the lungs themselves are the source of the metabolic acid','The respiratory response does not identify the acid source.')],
 'Breathing can reveal a systemic acid-base disorder','**Increased alveolar ventilation partially compensates for metabolic acid burden.**',['Assess ketones, lactate, renal function and other causes.','The response can fail with fatigue, sedation or neuromuscular impairment.'],'**Treat the metabolic cause and preserve necessary ventilation.**',['Do not sedate the breathing pattern away without a safe support plan.','Use blood gases to assess compensation.'],[['Primary problem','Metabolic acidosis'],['Response','Deep hyperventilation'],['Limit','Does not identify etiology']],[OV],style='clinical_scenario')

q('Breath sounds are quiet over both lungs in an obese patient breathing shallowly. Which statement is correct?', 'Reduced sound intensity is nonspecific and must be interpreted with effort, chest-wall factors and other signs',[
 ('Quiet sounds alone prove bilateral pneumothoraces','Several transmission and ventilation factors can cause quietness.'),('Quiet sounds alone establish normal lungs','They do not exclude disease.'),('Obesity makes all chest examination findings diagnostically meaningless','The examination still contributes when its limitations are recognized.')],
 'A quiet signal may arise from source or transmission','**Shallow airflow and a thick chest wall can reduce audibility.**',['Hyperinflation, pleural disease and obstruction are other possibilities.','Compare regions and assess percussion and expansion.'],'**Use objective testing when the clinical question remains unresolved.**',['Ensure adequate technique and tolerable positioning.','Do not force deep breathing that destabilizes an unwell patient.'],[['Source','Airflow/effort'],['Transmission','Chest wall/pleura'],['Interpretation','Combined examination']],[CH],style='clinical_scenario')

q('Why can tactile vocal fremitus be reduced in a patient with marked obesity despite no pleural fluid?', 'Chest-wall tissue can attenuate transmitted vibration',[
 ('Obesity necessarily blocks every bronchus','This is not the mechanism.'),('Fremitus directly measures alveolar oxygen concentration','It assesses mechanical transmission of voice vibration.'),('Reduced fremitus is uniquely diagnostic of pneumothorax','Several conditions reduce transmission.')],
 'Transmission signs depend on the entire pathway','**Voice vibration travels through airways, lung, pleura and chest wall.**',['The patient’s voice strength and examiner technique also matter.','Symmetrical comparison is more informative than an isolated absolute impression.'],'**Correlate with the rest of the examination and imaging.**',['Do not diagnose an effusion from one reduced-fremitus finding.','Use ultrasound when pleural fluid is the question.'],[['Signal','Voice vibration'],['Attenuation','Body wall and other barriers'],['Value','Comparative context']],[CH])

q('A patient has unilateral reduced chest expansion. Which interpretation is most accurate?', 'It localizes a mechanical or ventilatory asymmetry but does not distinguish collapse, effusion, pneumothorax or pain by itself',[
 ('It proves a pleural effusion specifically','Several processes reduce expansion.'),('It excludes chest-wall pain as a contributor','Pain can limit movement.'),('It establishes the exact affected lobe without other findings','The sign is not that anatomically precise.')],
 'Inspection and palpation localize before they diagnose','**Reduced motion can reflect lung, pleural, airway or chest-wall disease.**',['Combine percussion, sounds, tracheal position and symptoms.','Prior surgery or chronic deformity may explain a longstanding asymmetry.'],'**Choose confirmation according to stability and the likely process.**',['Look for acute dangerous causes first.','Compare with prior findings when available.'],[['Sign','Asymmetric movement'],['Differential','Several mechanical causes'],['Next step','Pattern integration']],[CH])

q('A localized chest-wall segment moves inward on inspiration and outward on expiration after blunt trauma. Which finding is described?', 'Paradoxical motion of a flail segment',[
 ('Bilateral lower-rib Hoover sign','That has a different distribution and hyperinflation context.'),('Normal inspiratory expansion','The motion is opposite to normal.'),('Central cyanosis','This is a color sign, not a mechanical motion pattern.')],
 'Structural instability can reverse local motion','**Adjacent rib fractures can detach a chest-wall segment mechanically.**',['Pain and associated pulmonary contusion can be major contributors to respiratory failure.','Positive-pressure support can alter the visible motion.'],'**Assess the whole trauma and respiratory status urgently.**',['Do not judge severity from the motion alone.','Provide appropriate analgesia and support while investigating associated injuries.'],[['Inspiration','Segment inward'],['Expiration','Segment outward'],['Associated problem','Contusion/pain and other trauma']],[CH],style='clinical_scenario')

q('An orthopneic patient with suspected bilateral diaphragmatic weakness has a substantial fall in vital capacity when supine. Which interpretation is appropriate?', 'The positional change supports diaphragmatic dysfunction but needs integration with other testing and the clinical context',[
 ('Any positional fall is uniquely diagnostic of motor-neuron disease','Several neuromuscular and mechanical causes exist.'),('Normal seated oxygen saturation excludes the finding’s importance','Nocturnal/supine hypoventilation may occur despite daytime saturation.'),('Vital capacity directly measures gas diffusion across the alveoli','It is a volume measurement rather than a diffusion measurement.')],
 'Position changes the load on a weak diaphragm','**Supine abdominal loading can reveal reduced inspiratory-muscle reserve.**',['The magnitude and test quality matter.','Obesity and other conditions can influence the change.'],'**Assess respiratory muscle function and sleep-related ventilation when indicated.**',['Use ultrasound, pressures or other tests according to expertise.','Evaluate the neurological/systemic cause.'],[['Seated','May mask weakness'],['Supine','Increased diaphragmatic load'],['Assessment','Integrated muscle/ventilation workup']],[OV],style='clinical_scenario')

q('A patient has drowsiness and shallow breathing while receiving supplemental oxygen; SpO2 is 97%. Which examination inference is correct?', 'Adequate measured saturation does not exclude hypoventilation and hypercapnia',[
 ('A saturation above 95% establishes normal PaCO2','Pulse oximetry does not measure CO2.'),('Drowsiness must therefore be nonrespiratory','Hypercapnia or sedative-related hypoventilation remains possible.'),('Supplemental oxygen guarantees adequate alveolar ventilation','It can improve oxygenation without correcting ventilation.')],
 'Assess oxygenation and ventilation separately','**A patient can retain CO2 while oxygen saturation remains acceptable on oxygen.**',['Observe depth, rate, airway and consciousness.','Review sedatives, neuromuscular disease and lung mechanics.'],'**Obtain a blood gas and provide appropriate ventilatory assessment/support.**',['Treat the cause rather than relying on oxygen alone.','Reassess promptly for deterioration.'],[['SpO2','Oxygenation'],['PaCO2','Ventilation-related measure'],['Clinical clues','Drowsiness/shallow breathing']],[OV],style='clinical_scenario')

q('During chest auscultation, what improves the validity of comparing breath sounds?', 'Listen over matched regions with consistent technique and adequate skin contact, noting respiratory phase and effort',[
 ('Compare one side during deep inspiration with the other during shallow expiration','Different breathing conditions can create false asymmetry.'),('Listen only through thick clothing to avoid all exposure','Clothing can attenuate sounds and generate artifacts.'),('Infer a regional lesion from one noisy recording without reassessment','Artifacts and technique need checking.')],
 'Technique controls the measurement conditions','**Symmetrical comparison helps distinguish pathology from variation.**',['Maintain patient comfort, privacy and tolerable breathing instructions.','Examine anterior, lateral and posterior regions as appropriate.'],'**Repeat uncertain findings before drawing a conclusion.**',['Do not exhaust a distressed patient with prolonged forced deep breathing.','Use imaging when the physical examination cannot answer the question.'],[['Comparison','Matched sites/conditions'],['Contact','Minimize artifacts'],['Interpretation','Respiratory phase and context']],[CH])

if __name__=='__main__':finalize('Clinical Examination',3,'Respiratory Examination','exam-respiratory',rows,24)
